{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Just Cause for Eviction Ordinance (JCO)","requirement":"A landlord may not terminate a residential tenancy without just cause. No-fault evictions, such as owner or family move-in, demolition, conversion, or a government order to vacate, require the landlord to pay relocation assistance.","key_value":null,"coverage_conditions":"Most residential properties in the City of Los Angeles not regulated by the City's Rent Stabilization Ordinance. Tenancy covered once the tenant has lived in the unit at least six months or the original lease expired. Can apply to buildings newer than October 1, 1978 and to single-family dwellings.","applicability":{"built_on_or_before":null,"built_after":"1978-10-01","date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":true,"other":"Properties not regulated by the City's RSO; single-family dwellings covered"},"exemptions":"Transient hotels, licensed care facilities, fraternity or sorority houses, owner's roommate, certain cooperatives, some nonprofit facilities for the homeless or short-term substance-abuse treatment centers, and some properties owned by HACLA or the government.","penalty":null,"effective_date":null,"citation":"Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":"Applies to properties not regulated by the City's Rent Stabilization Ordinance (RSO).","confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Non-payment of rent eviction threshold based on Fair Market Rent","requirement":"A landlord may not evict a tenant who falls behind in rent unless the amount owed is higher than the Fair Market Rent for the unit's bedroom size.","key_value":"Rent owed must exceed the Fair Market Rent for the unit's bedroom size","coverage_conditions":"Applies to all RSO and JCO rental units in the City of Los Angeles, whatever the unit's bedroom size.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":null,"min_units":null,"max_units":null,"owner_dependent":false,"other":"All RSO and JCO rental units in the City of Los Angeles"},"exemptions":null,"penalty":null,"effective_date":"2023-03-27","citation":"Evictions for Non-Payment of Rent","quoted_span":"Effective March 27, 2023, landlords may not evict a tenant who falls behind in rent unless the tenant owes an amount higher than the Fair Market Rent (FMR).","interaction":null,"confidence":0.7,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act (AB 1482) annual rent cap","requirement":"Annual rent increases for covered units are limited to 5% plus the regional change in the cost of living, or 10%, whichever is lower. The maximum allowable increase was 8.9% from August 1, 2024 to July 31, 2025.","key_value":"8.9% (Aug 1, 2024–Jul 31, 2025); 5% + CPI, max 10%","coverage_conditions":"Units in buildings older than 15 years, applied on a rolling basis, that are not already subject to the City's RSO.","applicability":{"built_on_or_before":null,"built_after":null,"date_basis":"construction_date","min_units":null,"max_units":null,"owner_dependent":true,"other":"Exempts units constructed within the last 15 years, applied on a rolling basis; single-family/condominium exemption depends on owner type and written notice"},"exemptions":"Units constructed within the last 15 years (rolling basis), units restricted to low or moderate income by recorded document, certain dormitories, a two-unit property whose second unit was owner-occupied for the whole tenancy, single-family homes and condominiums meeting the corporate-owner and written-notice conditions, and units subject to the City's RSO.","penalty":null,"effective_date":"2024-08-01","citation":"Cal. Civ. Code § 1947.12","quoted_span":"Effective August 1, 2024 to July 31, 2025, the maximum allowable increase is 8.9%.","interaction":"The JCO does not regulate rent increases; state law AB 1482 may regulate the rent amount in buildings older than 15 years.","confidence":0.8,"conflict_flag":false,"conflict_note":null}
